#include <vector>

/**
 * @brief 通过下滤操作维护堆的性质
 * @param heap       要调整的堆数组
 * @param index      当前节点索引
 * @param size       堆的有效大小（即当前堆的长度）
 */
static void sift_down(std::vector<int>& heap, int index, int size) {
    while (true) {
        int left = 2 * index + 1;
        int right = 2 * index + 2;
        int largest = index;

        // 找到左右子节点中较大的那个
        if (left < size && heap[left] > heap[largest]) {
            largest = left;
        }
        if (right < size && heap[right] > heap[largest]) {
            largest = right;
        }

        // 如果已经是最大值，无需继续下滤
        if (largest == index) {
            break;
        }

        // 交换当前节点和最大值节点
        std::swap(heap[index], heap[largest]);
        index = largest; // 继续下滤
    }
}

/**
 * @brief 堆排序算法实现
 * @param items 待排序的数组
 * @return 排序后的数组
 */
std::vector<int> heap_sort(std::vector<int> items) {
    std::vector<int> result = items;
    int total = static_cast<int>(result.size());

    // 构建最大堆
    for (int start = total / 2 - 1; start >= 0; --start) {
        sift_down(result, start, total);
    }

    // 依次将堆顶元素（最大值）与末尾元素交换，并调整堆
    for (int end = total - 1; end > 0; --end) {
        std::swap(result[0], result[end]); // 交换堆顶与末尾元素
        sift_down(result, 0, end); // 调整堆（不包括末尾元素）
    }

    return result;
}
```

